Video Consultation Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Video Consultation Service", "Video Consultation Service") {
    Component("Signaling_Room_Manager_Component", "Signaling & Room Manager Component", "Node.js", "Manages WebRTC signaling and rooms, forwarding WebSocket signaling from the API gateway and provisioning transport channels.")
    Component("SFU_Media_Worker_Component", "SFU Media Worker Component", "Mediasoup / C++ core", "Handles media routing and Selective Forwarding Unit (SFU) capabilities for video consultations.")
    Component("Bandwidth_Adaptability_Controller_Component", "Bandwidth Adaptability Controller Component", "Go", "Dynamically adjusts Simulcast and SVC layers based on network conditions for low-bandwidth resilience.")
}

Rel("Signaling_Room_Manager_Component", "SFU_Media_Worker_Component", "Provisions transport channels", "IPC")
Rel("Bandwidth_Adaptability_Controller_Component", "SFU_Media_Worker_Component", "Adjusts Simulcast/SVC layers dynamically", "In-memory API")

@enduml

E-Prescription Integration Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("E-Prescription Integration Container", "E-Prescription Integration Container") {
    Component("Prescription Router Component", "Prescription Router Component", "Node.js, TypeScript", "Routes and dispatches prescription payloads to regional adapters.")
    Component("EU National Gateway Adapter", "EU National Gateway Adapter", "Node.js, TypeScript, europe-west3", "Dispatches regional EU formats via outbound mTLS with pinned IPs and certificates.")
    Component("US Pharmacy Network Adapter", "US Pharmacy Network Adapter", "Node.js, TypeScript, us-central1, HL7 FHIR", "Transmits HL7 FHIR payloads via outbound mTLS to US pharmacy networks.")
    Component("Outbox Pattern / Reliability Component", "Outbox Pattern / Reliability Component", "Node.js, TypeScript, Google Cloud Pub/Sub", "Handles reliable message queuing for transactional outbox pattern and event publishing.")
}

Rel("Prescription Router Component", "EU National Gateway Adapter", "Dispatches regional EU formats via outbound mTLS with pinned IPs and certificates", "mTLS")
Rel("Prescription Router Component", "US Pharmacy Network Adapter", "Transmits HL7 FHIR payloads via outbound mTLS", "mTLS / HL7 FHIR")

@enduml

Data Tier.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Data Tier container

Container_Boundary(data_tier, "Data Tier") {
    Component(cloud_sql_postgresql, "Cloud SQL PostgreSQL", "Google Cloud SQL, PostgreSQL, Row-Level Security, WORM tables", "Relational store utilizing Row-Level Security (RLS) and append-only WORM tables for auditability with CMEK.")
    Component(memorystore_redis, "Memorystore Redis", "Google Cloud Memorystore, Redis", "Low-latency cache with pub/sub for dynamic consent token validation.")
}

Rel(cloud_sql_postgresql, memorystore_redis, "Provides backing store and caching coordination for data access.", "")

@enduml

Messaging & Observability.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(messaging_observability, "Messaging & Observability") {
    Component(Event Broker Component, "Event Broker Component", "Google Cloud Pub/Sub", "Manages regional event-driven messaging and Dead-Letter Queues with CMEK.")
    Component(Telemetry Collector Component, "Telemetry Collector Component", "OpenTelemetry Collector", "Handles distributed tracing, metrics, and telemetry data masking.")
    Component(Audit Logger Component, "Audit Logger Component", "Cloud Audit Logs", "Sinks immutable audit trails via HTTPS API to Cloud Storage or BigQuery.")
}

Rel(Telemetry Collector Component, Event Broker Component, "Publishes operational telemetry events")
Rel(Audit Logger Component, Event Broker Component, "Publishes security and audit events")
@enduml
